using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.SceneManagement;using GameActions;using Newtonsoft.Json;
namespace AssetPipeline.Editor
{
 [InitializeOnLoad]public static class GroundCrackReview
 {
  const string Stage="AssetStaging/VFXUpgrade/",Root="Assets/Game/VFX/Combat/";
  static GroundCrackReview(){EditorApplication.update+=()=>{if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(Stage+"POMReview.request"))return;File.Delete(Stage+"POMReview.request");Run();};}
  static byte[] Capture(Camera camera,string name)
  {
   var rt=RenderTexture.GetTemporary(1280,720,24,RenderTextureFormat.ARGB32);var old=RenderTexture.active;camera.targetTexture=rt;camera.Render();camera.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();var pixels=image.GetRawTextureData<byte>().ToArray();File.WriteAllBytes(Stage+name+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);camera.targetTexture=null;RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);return pixels;
  }
  static void Run()
  {
   var prior=SceneManager.GetActiveScene();var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(scene);Material simple=null;
   try
   {
    foreach(var path in new[]{"Graphs/SG_GroundCrack_POM.shadergraph","Graphs/DrillCraterDecal.shadergraph"}){var shader=AssetDatabase.LoadAssetAtPath<Shader>(Root+path);if(!shader)throw new Exception("Missing "+path);var errors=ShaderUtil.GetShaderMessages(shader).Where(e=>e.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error).ToArray();if(errors.Length>0)throw new Exception(string.Join(";",errors.Select(e=>e.message)));}
    Vector3 centre=new Vector3(200,0,0);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="POM review floor";floor.layer=31;floor.transform.position=centre+Vector3.down*.1f;floor.transform.localScale=new Vector3(12,.2f,12);var real=AssetDatabase.LoadAssetAtPath<Material>("Assets/Game/Environment/SovietFacility/Materials/SV_Concrete_Damp.mat");floor.GetComponent<Renderer>().sharedMaterial=real;
    RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);var light=new GameObject("POM grazing light").AddComponent<Light>();light.type=LightType.Directional;light.transform.rotation=Quaternion.Euler(30,-40,0);light.intensity=1.5f;light.cullingMask=1<<31;
    var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"DrillCrater_1.prefab"),scene);foreach(var t in go.GetComponentsInChildren<Transform>())t.gameObject.layer=31;go.transform.position=centre+Vector3.up*.008f;go.transform.rotation=Quaternion.Euler(90,0,0);go.transform.localScale=Vector3.one*4;var crack=go.GetComponent<GroundCrackImpact>();crack.enabled=false;crack.distantDecal.enabled=false;crack.parallaxMesh.enabled=true;
    var camera=new GameObject("POM review camera").AddComponent<Camera>();camera.cullingMask=1<<31;camera.transform.SetPositionAndRotation(centre+new Vector3(0,1.8f,-3.5f),Quaternion.LookRotation(new Vector3(0,-1.8f,3.5f)));camera.nearClipPlane=.03f;camera.farClipPlane=20;camera.fieldOfView=60;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.06f,.07f,.08f);camera.GetUniversalAdditionalCameraData().requiresDepthTexture=true;
    var block=new MaterialPropertyBlock();block.SetFloat("_HeightAmplitudeCm",0);block.SetFloat("_CrackOpacity",1);crack.parallaxMesh.SetPropertyBlock(block);var zero=Capture(camera,"pom_zero_depth");block.SetFloat("_HeightAmplitudeCm",35);crack.parallaxMesh.SetPropertyBlock(block);var deep=Capture(camera,"pom_35cm");long difference=zero.Zip(deep,(a,b)=>(long)Math.Abs(a-b)).Sum();
    block.SetFloat("_HeightAmplitudeCm",20);crack.parallaxMesh.SetPropertyBlock(block);Capture(camera,"pom_20cm");camera.transform.SetPositionAndRotation(centre+new Vector3(0,5,-.01f),Quaternion.Euler(90,0,0));Capture(camera,"pom_top");
    var rubble=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"ConcreteImpactHeavy.prefab");if(rubble){var debris=(GameObject)PrefabUtility.InstantiatePrefab(rubble,scene);debris.transform.position=centre+Vector3.up*.08f;foreach(var t in debris.GetComponentsInChildren<Transform>())t.gameObject.layer=31;Physics.SyncTransforms();foreach(var ps in debris.GetComponentsInChildren<ParticleSystem>())ps.Simulate(.35f,false,true,true);camera.transform.SetPositionAndRotation(centre+new Vector3(4,2.8f,-4),Quaternion.LookRotation(new Vector3(-4,-2.4f,4)));Capture(camera,"ground_impact_isolated");foreach(var ps in debris.GetComponentsInChildren<ParticleSystem>())ps.Simulate(.65f,false,false,true);Capture(camera,"ground_impact_dust_late");var dustPS=debris.GetComponentsInChildren<ParticleSystem>().First(x=>x.name=="Expanding ground dust");var buffer=new ParticleSystem.Particle[256];int count=dustPS.GetParticles(buffer);File.WriteAllText(Stage+"dust_spread.json",JsonConvert.SerializeObject(new{count,meanRadius=buffer.Take(count).Average(x=>Vector3.ProjectOnPlane(x.position-centre,Vector3.up).magnitude),maximumRadius=buffer.Take(count).Max(x=>Vector3.ProjectOnPlane(x.position-centre,Vector3.up).magnitude),maximumHeight=buffer.Take(count).Max(x=>x.position.y)},Formatting.Indented));UnityEngine.Object.DestroyImmediate(debris);}
    if(!File.Exists(Root+"Preview/GroundCrackImpactReview.unity")){go.SetActive(false);var demo=new GameObject("Ground impact preview - light and heavy");demo.transform.position=centre;var stamps=demo.AddComponent<GroundImpactDecals>();stamps.prefabs=new[]{AssetDatabase.LoadAssetAtPath<GameObject>(Root+"DrillCrater_1.prefab"),AssetDatabase.LoadAssetAtPath<GameObject>(Root+"DrillCrater_2.prefab")};stamps.lightDebris=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"ConcreteImpactLight.prefab");stamps.heavyDebris=rubble;demo.AddComponent<GroundImpactPreview>().stamps=stamps;camera.tag="MainCamera";camera.cullingMask=~0;light.cullingMask=~0;floor.layer=0;EditorSceneManager.SaveScene(scene,Root+"Preview/GroundCrackImpactReview.unity");}
    simple=new Material(Shader.Find("Universal Render Pipeline/Lit"));simple.SetColor("_BaseColor",new Color(.3f,.32f,.34f));floor.GetComponent<Renderer>().sharedMaterial=simple;camera.transform.SetPositionAndRotation(centre+new Vector3(0,1.8f,-3.5f),Quaternion.LookRotation(new Vector3(0,-1.8f,3.5f)));Capture(camera,"pom_plain_concrete");
    File.WriteAllText(Stage+"pom_review.json",JsonConvert.SerializeObject(new{passed=difference>50000,difference,realFloorShader=real.shader.name,noBaseColor=!crack.parallaxMesh.sharedMaterial.HasProperty("_BaseMap"),noEmission=!crack.parallaxMesh.sharedMaterial.HasProperty("_EmissionColor")},Formatting.Indented));
   }catch(Exception e){File.WriteAllText(Stage+"pom_review.json",e.ToString());Debug.LogException(e);}finally{if(simple)UnityEngine.Object.DestroyImmediate(simple);SceneManager.SetActiveScene(prior);EditorSceneManager.CloseScene(scene,true);}
  }
 }
}
